79	template <typename Eq = std::equal_to<>, typename T1, typename T2>
80	constexpr bool equal(T1&& t1, T2&& t2, Eq&& eq = {}) {
81	  auto first1 = t1.begin();
82	  auto last1 = t1.end();
83	  auto first2 = t2.begin();
84	  auto last2 = t2.end();
85	
86	  for (; first1 != last1; ++first1, ++first2) {
87	    if (first2 == last2 || !eq(*first1, *first2)) {
88	      return false;
89	    }
90	  }
91	  return first2 == last2;
92	}
93	
94	template <typename Cmp = std::less<>, typename T1, typename T2>
95	constexpr bool lexicographical_compare(T1&& t1, T2&& t2, Cmp&& cmp = {}) {
96	  auto first1 = t1.begin();
97	  auto last1 = t1.end();
98	  auto first2 = t2.begin();
99	  auto last2 = t2.end();
100	
101	  // copied from std::lexicographical_compare
102	  for (; (first1 != last1) && (first2 != last2); ++first1, (void)++first2) {
103	    if (cmp(*first1, *first2)) {
104	      return true;
105	    }
106	    if (cmp(*first2, *first1)) {
107	      return false;
108	    }
109	  }
110	  return (first1 == last1) && (first2 != last2);
111	}
