113	template <typename T>
114	constexpr std::size_t popcount(T x) noexcept {
115	#if defined(__cpp_lib_bitops) && __cpp_lib_bitops >= 201907L
116	  return static_cast<std::size_t>(std::popcount(x));
117	#else
118	  std::size_t c = 0;
119	  while (x > 0) {
120	    x &= x - 1;
121	    ++c;
122	  }
123	  return c;
124	#endif
125	}
