129	template <typename Cmp = std::less<>, typename ForwardIt, typename E>
130	constexpr ForwardIt lower_bound(ForwardIt first, ForwardIt last, E&& e, Cmp&& comp = {}) {
131	  auto count = std::distance(first, last);
132	  while (count > 0) {
133	    auto it = first;
134	    auto step = count / 2;
135	    std::advance(it, step);
136	    if (comp(*it, e)) {
137	      first = ++it;
138	      count -= step + 1;
139	    } else {
140	      count = step;
141	    }
142	  }
143	  return first;
144	}
