159	template <typename E = void, typename Cmp = std::less<E>, typename = void>
160	class indexing {
161	  [[nodiscard]] static constexpr auto get_indices() noexcept {
162	    // reverse result index mapping
163	    std::array<std::size_t, enum_count<E>()> rev_res{};
164	
165	    // std::iota
166	    for (std::size_t i = 0; i < enum_count<E>(); ++i) {
167	      rev_res[i] = i;
168	    }
169	
170	    constexpr auto orig_values = enum_values<E>();
171	    constexpr Cmp cmp{};
172	
173	    // ~std::sort
174	    for (std::size_t i = 0; i < enum_count<E>(); ++i) {
175	      for (std::size_t j = i + 1; j < enum_count<E>(); ++j) {
176	        if (cmp(orig_values[rev_res[j]], orig_values[rev_res[i]])) {
177	          auto tmp = rev_res[i];
178	          rev_res[i] = rev_res[j];
179	          rev_res[j] = tmp;
180	        }
181	      }
182	    }
183	
184	    std::array<E, enum_count<E>()> sorted_values{};
185	    // reverse the sorted indices
186	    std::array<std::size_t, enum_count<E>()> res{};
187	    for (std::size_t i = 0; i < enum_count<E>(); ++i) {
188	      res[rev_res[i]] = i;
189	      sorted_values[i] = orig_values[rev_res[i]];
190	    }
191	
192	    return std::pair{sorted_values, res};
193	  }
194	
195	  static constexpr auto indices = get_indices();
196	
197	 public:
198	  [[nodiscard]] static constexpr const E* begin() noexcept { return indices.first.data(); }
199	
200	  [[nodiscard]] static constexpr const E* end() noexcept { return indices.first.data() + indices.first.size(); }
201	
202	  [[nodiscard]] static constexpr const E* it(std::size_t i) noexcept { return indices.first.data() + i; }
203	
204	  [[nodiscard]] static constexpr optional<std::size_t> at(E val) noexcept {
205	    if (auto i = enum_index(val)) {
206	      return indices.second[*i];
207	    }
208	    return {};
209	  }
210	};
