236	template <typename E = void, typename Cmp = std::less<>, typename = void>
237	struct name_sort_impl {
238	  [[nodiscard]] constexpr bool operator()(E e1, E e2) const { return Cmp{}(enum_name(e1), enum_name(e2)); }
239	};
