241	template <typename Cmp>
242	struct name_sort_impl<void, Cmp> {
243	  using is_transparent = std::true_type;
244	
245	  template <typename C = Cmp, typename = void>
246	  struct FullCmp : C {};
247	
248	  template <typename C>
249	  struct FullCmp<C, std::enable_if_t<!std::is_invocable_v<C, string_view, string_view> && std::is_invocable_v<C, char_type, char_type>>> {
250	    [[nodiscard]] constexpr bool operator()(string_view s1, string_view s2) const { return lexicographical_compare<C>(s1, s2); }
251	  };
252	
253	  template <typename T>
254	  using cmp_arg_t = std::conditional_t<std::is_enum_v<std::decay_t<T>> || std::is_constructible_v<string_view, T>, string_view, T>;
255	
256	  template <typename T>
257	  [[nodiscard]] static constexpr decltype(auto) cmp_arg(T&& value) {
258	    using D = std::decay_t<T>;
259	    if constexpr (std::is_enum_v<D>) {
260	      return enum_name(value);
261	    } else if constexpr (std::is_constructible_v<string_view, T>) {
262	      return string_view{std::forward<T>(value)};
263	    } else {
264	      return std::forward<T>(value);
265	    }
266	  }
267	
268	  template <typename E1, typename E2>
269	  [[nodiscard]] constexpr std::enable_if_t<
270	      // at least one of need to be an enum type
271	      (std::is_enum_v<std::decay_t<E1>> || std::is_enum_v<std::decay_t<E2>>) &&
272	      // if both is enum, only accept if the same enum
273	      (!std::is_enum_v<std::decay_t<E1>> || !std::is_enum_v<std::decay_t<E2>> || std::is_same_v<std::decay_t<E1>, std::decay_t<E2>>) &&
274	      // is invocable with comparator
275	      (std::is_invocable_r_v<bool, FullCmp<>, cmp_arg_t<E1>, cmp_arg_t<E2>>),
276	      bool>
277	  operator()(E1&& e1, E2&& e2) const {
278	    constexpr FullCmp<> cmp{};
279	    return cmp(cmp_arg(std::forward<E1>(e1)), cmp_arg(std::forward<E2>(e2)));
280	  }
281	};
