285	template <typename Parent, typename Iterator, typename Getter, typename Predicate>
286	struct FilteredIterator {
287	  Parent parent;
288	  Iterator first;
289	  Iterator last;
290	  Iterator current;
291	  Getter getter;
292	  Predicate predicate;
293	
294	  using iterator_category = std::bidirectional_iterator_tag;
295	  using reference = std::invoke_result_t<Getter, Parent, Iterator>;
296	  using value_type = std::remove_cv_t<std::remove_reference_t<reference>>;
297	  using difference_type = std::ptrdiff_t;
298	  using pointer = std::add_pointer_t<std::remove_reference_t<reference>>;
299	
300	  constexpr FilteredIterator() noexcept = default;
301	  constexpr FilteredIterator(const FilteredIterator&) = default;
302	  constexpr FilteredIterator& operator=(const FilteredIterator&) = default;
303	  constexpr FilteredIterator(FilteredIterator&&) noexcept = default;
304	  constexpr FilteredIterator& operator=(FilteredIterator&&) noexcept = default;
305	
306	  template <typename OtherParent, typename OtherIterator, typename = std::enable_if_t<std::is_convertible_v<OtherParent, Parent> && std::is_convertible_v<OtherIterator, Iterator>>*>
307	  constexpr explicit FilteredIterator(const FilteredIterator<OtherParent, OtherIterator, Getter, Predicate>& other)
308	      : parent(other.parent), first(other.first), last(other.last), current(other.current), getter(other.getter), predicate(other.predicate) {}
309	
310	  constexpr FilteredIterator(Parent p, Iterator begin, Iterator end, Iterator curr, Getter get = {}, Predicate pred = {})
311	      : parent(p), first(std::move(begin)), last(std::move(end)), current(std::move(curr)), getter{std::move(get)}, predicate{std::move(pred)} {
312	    if (current == first && !predicate(parent, current)) {
313	      ++*this;
314	    }
315	  }
316	
317	  [[nodiscard]] constexpr reference operator*() const { return getter(parent, current); }
318	
319	  [[nodiscard]] constexpr pointer operator->() const { return std::addressof(**this); }
320	
321	  constexpr FilteredIterator& operator++() {
322	    do {
323	      ++current;
324	    } while (current != last && !predicate(parent, current));
325	    return *this;
326	  }
327	
328	  [[nodiscard]] constexpr FilteredIterator operator++(int) {
329	    FilteredIterator cp = *this;
330	    ++*this;
331	    return cp;
332	  }
333	
334	  constexpr FilteredIterator& operator--() {
335	    do {
336	      --current;
337	    } while (current != first && !predicate(parent, current));
338	    return *this;
339	  }
340	
341	  [[nodiscard]] constexpr FilteredIterator operator--(int) {
342	    FilteredIterator cp = *this;
343	    --*this;
344	    return cp;
345	  }
346	
347	  [[nodiscard]] friend constexpr bool operator==(const FilteredIterator& lhs, const FilteredIterator& rhs) { return lhs.current == rhs.current; }
348	
349	  [[nodiscard]] friend constexpr bool operator!=(const FilteredIterator& lhs, const FilteredIterator& rhs) { return lhs.current != rhs.current; }
350	};
