352	template <typename T>
353	constexpr int countr_zero(T x) noexcept {
354	#if defined(__cpp_lib_bitops) && __cpp_lib_bitops >= 201907L
355	  return std::countr_zero(x);
356	#elif defined(_MSC_VER) && !defined(__clang__)
357	  unsigned long index;
358	  if constexpr (sizeof(T) <= sizeof(unsigned long)) {
359	    return _BitScanForward(&index, static_cast<unsigned long>(x)) ? static_cast<int>(index) : static_cast<int>(sizeof(T) * 8);
360	  } else {
361	#  ifdef _WIN64
362	    return _BitScanForward64(&index, static_cast<unsigned __int64>(x)) ? static_cast<int>(index) : static_cast<int>(sizeof(T) * 8);
363	#  else
364	    if (_BitScanForward(&index, static_cast<unsigned long>(x))) { return static_cast<int>(index); }
365	    return _BitScanForward(&index, static_cast<unsigned long>(x >> 32)) ? static_cast<int>(index) + 32 : static_cast<int>(sizeof(T) * 8);
366	#  endif
367	  }
368	#else
369	  if constexpr (sizeof(T) <= sizeof(unsigned int)) {
370	    return x ? __builtin_ctz(static_cast<unsigned int>(x)) : static_cast<int>(sizeof(T) * 8);
371	  } else if constexpr (sizeof(T) <= sizeof(unsigned long)) {
372	    return x ? __builtin_ctzl(static_cast<unsigned long>(x)) : static_cast<int>(sizeof(T) * 8);
373	  } else {
374	    return x ? __builtin_ctzll(static_cast<unsigned long long>(x)) : static_cast<int>(sizeof(T) * 8);
375	  }
376	#endif
377	}
378	
379	template <typename T>
380	constexpr int countl_zero(T x) noexcept {
381	#if defined(__cpp_lib_bitops) && __cpp_lib_bitops >= 201907L
382	  return std::countl_zero(x);
383	#elif defined(_MSC_VER) && !defined(__clang__)
384	  unsigned long index;
385	  if constexpr (sizeof(T) <= sizeof(unsigned long)) {
386	    return _BitScanReverse(&index, static_cast<unsigned long>(x)) ? static_cast<int>(sizeof(T) * 8) - static_cast<int>(index) - 1 : static_cast<int>(sizeof(T) * 8);
387	  } else {
388	#  ifdef _WIN64
389	    return _BitScanReverse64(&index, static_cast<unsigned __int64>(x)) ? static_cast<int>(sizeof(T) * 8) - static_cast<int>(index) - 1 : static_cast<int>(sizeof(T) * 8);
390	#  else
391	    if (_BitScanReverse(&index, static_cast<unsigned long>(x >> 32))) { return static_cast<int>(sizeof(T) * 8) - static_cast<int>(index) - 33; }
392	    return _BitScanReverse(&index, static_cast<unsigned long>(x)) ? static_cast<int>(sizeof(T) * 8) - static_cast<int>(index) - 1 : static_cast<int>(sizeof(T) * 8);
393	#  endif
394	  }
395	#else
396	  // __builtin_clz* counts leading zeros in the promoted type width, not in T.
397	  // We must subtract the extra bits introduced by zero-extension.
398	  if constexpr (sizeof(T) <= sizeof(unsigned int)) {
399	    return x ? __builtin_clz(static_cast<unsigned int>(x)) - static_cast<int>((sizeof(unsigned int) - sizeof(T)) * 8) : static_cast<int>(sizeof(T) * 8);
400	  } else if constexpr (sizeof(T) <= sizeof(unsigned long)) {
401	    return x ? __builtin_clzl(static_cast<unsigned long>(x)) - static_cast<int>((sizeof(unsigned long) - sizeof(T)) * 8) : static_cast<int>(sizeof(T) * 8);
402	  } else {
403	    return x ? __builtin_clzll(static_cast<unsigned long long>(x)) - static_cast<int>((sizeof(unsigned long long) - sizeof(T)) * 8) : static_cast<int>(sizeof(T) * 8);
404	  }
405	#endif
406	}
