408	template <typename T>
409	constexpr int bit_width(T x) noexcept {
410	#if defined(__cpp_lib_int_pow2) && __cpp_lib_int_pow2 >= 202002L
411	  return std::bit_width(x);
412	#else
413	  return std::numeric_limits<T>::digits - countl_zero(x);
414	#endif
415	}
