417	template <typename E, typename Index>
418	constexpr bool valid_indexing() noexcept {
419	  constexpr std::size_t count = enum_count<E>();
420	  if constexpr (count == 0) {
421	    return false;
422	  } else {
423	    std::array<bool, count> used_indices{};
424	    for (const auto value : enum_values<E>()) {
425	      const auto index = Index::at(value);
426	      if (!index || *index >= count || used_indices[*index]) {
427	        return false;
428	      }
429	      used_indices[*index] = true;
430	    }
431	    return true;
432	  }
433	}
