1428	  std::size_t operator()(const magic_enum::containers::bitset<E, Index>& bs) const noexcept {
1429	    if constexpr (magic_enum::enum_count<E>() <= sizeof(unsigned long long) * 8) {
1430	      return std::hash<unsigned long long>{}(bs.to_ullong(magic_enum::containers::raw_access));
1431	    } else {
1432	      unsigned long long low_bits = 0;
1433	      std::size_t seed = 0;
1434	      bool has_high_bits = false;
1435	      for (const auto value : bs) {
1436	        const auto index = Index::at(value);
1437	        MAGIC_ENUM_ASSERT(index);
1438	        if (*index < sizeof(low_bits) * 8) {
1439	          low_bits |= 1ULL << *index;
1440	        } else {
1441	          if (!has_high_bits) {
1442	            seed = std::hash<unsigned long long>{}(low_bits);
1443	            has_high_bits = true;
1444	          }
1445	          const auto index_hash = std::hash<std::size_t>{}(*index);
1446	          seed ^= index_hash + std::size_t{0x9e3779b9U} + (seed << 6) + (seed >> 2);
1447	        }
1448	      }
1449	      return has_high_bits ? seed : std::hash<unsigned long long>{}(low_bits);
1450	    }
